package com.bank.replication.service;
import com.bank.replication.model.WalRecord;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class ReplicationManager {
    private static final Logger log = Logger.getLogger(ReplicationManager.class.getName());
    static {
        Handler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false); log.addHandler(h);
    }
    private final List<WalRecord> primary = new ArrayList<>();
    private final List<WalRecord> replica = new ArrayList<>();
    private final BlockingQueue<WalRecord> asyncQueue = new LinkedBlockingQueue<>();

    // SYNCHRONOUS: block until replica confirms → RPO = 0
    public void commitSync(WalRecord w) {
        primary.add(w);
        replica.add(w);                       // simulate waiting for replica ack
        log.info(() -> "SYNC commit " + w.getTxnId() + " acked by replica (RPO=0)");
    }
    // ASYNCHRONOUS: confirm now, ship later → small loss window
    public void commitAsync(WalRecord w) {
        primary.add(w);
        asyncQueue.offer(w);                  // not yet on replica
        log.info(() -> "ASYNC commit " + w.getTxnId() + " acked by primary (replica pending)");
    }
    public void flushAsync() {                // background shipper
        asyncQueue.drainTo(replica);
    }
    public void simulateCrash() {
        int lost = asyncQueue.size();
        log.severe(() -> "CRASH: primary lost, " + lost + " async records not on replica (data loss)");
        asyncQueue.clear();
    }
    public int replicaCount() { return replica.size(); }
}
