package com.bank.replication;
import com.bank.replication.model.WalRecord;
import com.bank.replication.service.ReplicationManager;
import java.math.BigDecimal;
import java.util.logging.*;

public class ReplicationDemo {
    public static void main(String[] args) {
        ReplicationManager rm = new ReplicationManager();
        rm.commitSync(new WalRecord("TXF-1","SAV2001", new BigDecimal("50000")));   // safe
        rm.commitAsync(new WalRecord("TXF-2","SAV2001", new BigDecimal("20000")));  // pending
        rm.simulateCrash();                                                          // async one lost
        System.out.println("replica has " + rm.replicaCount() + " record(s)");      // 1 (the sync one)
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), formatMessage(r));
    }
}
